INSERT IGNORE INTO `model_template` (`id`, `provider`, `model_name`, `model_type`, `template`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,'OpenAI','gpt-4o','llm','{\"id\": 69010, \"meta\": {\"status\": 0, \"protocol\": \"openai\", \"capability\": {\"json_mode\": false, \"reasoning\": false, \"max_tokens\": 128000, \"input_modal\": [\"text\", \"image\"], \"input_tokens\": 128000, \"output_modal\": [\"text\"], \"function_call\": true, \"output_tokens\": 16384, \"prefix_caching\": false, \"prefill_response\": false}, \"conn_config\": {\"stop\": [], \"model\": \"\", \"top_k\": 0, \"top_p\": 1, \"custom\": {}, \"openai\": {\"by_azure\": false, \"api_version\": \"\", \"response_format\": {\"type\": \"text\", \"jsonschema\": null}}, \"api_key\": \"\", \"timeout\": \"0s\", \"base_url\": \"https://api.openai.com/v1\", \"max_tokens\": 4096, \"temperature\": 0.7, \"presence_penalty\": 0, \"frequency_penalty\": 0}}, \"name\": \"GPT-4o\", \"icon_uri\": \"default_icon/openai_v2.png\", \"icon_url\": \"\", \"description\": {\"en\": \"Multi-modal, 320ms, 88.7% MMLU, excels in education, customer support, health, and entertainment.\", \"zh\": \"gpt 模型简介\"}, \"default_parameters\": [{\"max\": \"1\", \"min\": \"0\", \"desc\": {\"en\": \"**Temperature**:\\n\\n- When you increase this value, the model outputs more diverse and innovative content; when you decrease it, the model outputs less diverse content that strictly follows the given instructions.\\n- It is recommended not to adjust this value with \\\"Top p\\\" at the same time.\", \"zh\": \"- **temperature**: 调高温度会使得模型的输出更多样性和创新性，反之，降低温度会使输出内容更加遵循指令要求但减少多样性。建议不要与\\\"Top p\\\"同时调整。\"}, \"name\": \"temperature\", \"type\": \"float\", \"label\": {\"en\": \"Temperature\", \"zh\": \"生成随机性\"}, \"style\": {\"label\": {\"en\": \"Generation diversity\", \"zh\": \"生成多样性\"}, \"widget\": \"slider\"}, \"options\": [], \"precision\": 1, \"default_val\": {\"balance\": \"0.8\", \"precise\": \"0.3\", \"creative\": \"1\", \"default_val\": \"1.0\"}}, {\"max\": \"4096\", \"min\": \"1\", \"desc\": {\"en\": \"You can specify the maximum length of the tokens output through this value. Typically, 100 tokens are approximately equal to 150 Chinese characters.\", \"zh\": \"控制模型输出的Tokens 长度上限。通常 100 Tokens 约等于 150 个中文汉字。\"}, \"name\": \"max_tokens\", \"type\": \"int\", \"label\": {\"en\": \"Response max length\", \"zh\": \"最大回复长度\"}, \"style\": {\"label\": {\"en\": \"Input and output settings\", \"zh\": \"输入及输出设置\"}, \"widget\": \"slider\"}, \"options\": [], \"default_val\": {\"default_val\": \"4096\"}}, {\"max\": \"1\", \"min\": \"0\", \"desc\": {\"en\": \"**Top P**:\\n\\n- An alternative to sampling with temperature, where only tokens within the top p probability mass are considered. For example, 0.1 means only the top 10% probability mass tokens are considered.\\n- We recommend altering this or temperature, but not both.\", \"zh\": \"- **Top p 为累计概率**: 模型在生成输出时会从概率最高的词汇开始选择，直到这些词汇的总概率累积达到Top p 值。这样可以限制模型只选择这些高概率的词汇，从而控制输出内容的多样性。建议不要与\\\"生成随机性\\\"同时调整。\"}, \"name\": \"top_p\", \"type\": \"float\", \"label\": {\"en\": \"Top P\", \"zh\": \"Top P\"}, \"style\": {\"label\": {\"en\": \"Generation diversity\", \"zh\": \"生成多样性\"}, \"widget\": \"slider\"}, \"options\": [], \"precision\": 2, \"default_val\": {\"default_val\": \"0.7\"}}, {\"max\": \"2\", \"min\": \"-2\", \"desc\": {\"en\": \"**Frequency Penalty**: When positive, it discourages the model from repeating the same words and phrases, thereby increasing the diversity of the output.\", \"zh\": \"- **frequency penalty**: 当该值为正时，会阻止模型频繁使用相同的词汇和短语，从而增加输出内容的多样性。\"}, \"name\": \"frequency_penalty\", \"type\": \"float\", \"label\": {\"en\": \"Frequency penalty\", \"zh\": \"重复语句惩罚\"}, \"style\": {\"label\": {\"en\": \"Generation diversity\", \"zh\": \"生成多样性\"}, \"widget\": \"slider\"}, \"options\": [], \"precision\": 2, \"default_val\": {\"default_val\": \"0\"}}, {\"max\": \"2\", \"min\": \"-2\", \"desc\": {\"en\": \"**Presence Penalty**: When positive, it prevents the model from discussing the same topics repeatedly, thereby increasing the diversity of the output.\", \"zh\": \"- **presence penalty**: 当该值为正时，会阻止模型频繁讨论相同的主题，从而增加输出内容的多样性\"}, \"name\": \"presence_penalty\", \"type\": \"float\", \"label\": {\"en\": \"Presence penalty\", \"zh\": \"重复主题惩罚\"}, \"style\": {\"label\": {\"en\": \"Generation diversity\", \"zh\": \"生成多样性\"}, \"widget\": \"slider\"}, \"options\": [], \"precision\": 2, \"default_val\": {\"default_val\": \"0\"}}, {\"max\": \"\", \"min\": \"\", \"desc\": {\"en\": \"**Response Format**:\\n\\n- **Text**: Replies in plain text format\\n- **Markdown**: Uses Markdown format for replies\\n- **JSON**: Uses JSON format for replies\", \"zh\": \"- **文本**: 使用普通文本格式回复\\n- **Markdown**: 将引导模型使用Markdown格式输出回复\\n- **JSON**: 将引导模型使用JSON格式输出\"}, \"name\": \"response_format\", \"type\": \"int\", \"label\": {\"en\": \"Response format\", \"zh\": \"输出格式\"}, \"style\": {\"label\": {\"en\": \"Input and output settings\", \"zh\": \"输入及输出设置\"}, \"widget\": \"radio_buttons\"}, \"options\": [{\"label\": \"Text\", \"value\": \"0\"}, {\"label\": \"Markdown\", \"value\": \"1\"}, {\"label\": \"JSON\", \"value\": \"2\"}], \"default_val\": {\"default_val\": \"0\"}}]}',1754027126932,1754027126932,NULL),(2,'Qwen','qwen-plus-latest','llm','{\"id\": 2005, \"meta\": {\"name\": \"qwen-plus-latest\", \"status\": 0, \"protocol\": \"qwen\", \"capability\": {\"json_mode\": false, \"reasoning\": false, \"max_tokens\": 128000, \"input_modal\": [\"text\"], \"input_tokens\": 128000, \"output_modal\": [\"text\"], \"function_call\": true, \"output_tokens\": 16384, \"prefix_caching\": false, \"prefill_response\": false}, \"conn_config\": {\"ark\": null, \"qwen\": {\"response_format\": {\"type\": \"text\", \"jsonschema\": null}}, \"stop\": [], \"model\": \"qwen-plus-latest\", \"top_k\": 0, \"top_p\": 1, \"claude\": null, \"custom\": {}, \"gemini\": null, \"openai\": null, \"api_key\": \"REPLACE_ME_MODEL_API_KEY\", \"timeout\": \"10s\", \"base_url\": \"https://dashscope.aliyuncs.com/compatible-mode/v1\", \"deepseek\": null, \"max_tokens\": 4096, \"temperature\": 0.7, \"presence_penalty\": 0, \"frequency_penalty\": 0}}, \"name\": \"qwen-plus-latest\", \"icon_uri\": \"default_icon/qwen_v2.png\", \"icon_url\": \"\", \"description\": {\"en\": \"qwen model description\", \"zh\": \"通义千问模型\"}, \"default_parameters\": [{\"max\": \"1\", \"min\": \"0\", \"desc\": {\"en\": \"**Temperature**:\\\\n\\\\n- When you increase this value, the model outputs more diverse and innovative content; when you decrease it, the model outputs less diverse content that strictly follows the given instructions.\\\\n- It is recommended not to adjust this value with \\\\\\\"Top p\\\\\\\" at the same time.\", \"zh\": \"- **temperature**: 调高温度会使得模型的输出更多样性和创新性，反之，降低温度会使输出内容更加遵循指令要求但减少多样性。建议不要与“Top p”同时调整。\"}, \"name\": \"temperature\", \"type\": \"float\", \"label\": {\"en\": \"Temperature\", \"zh\": \"生成随机性\"}, \"style\": {\"label\": {\"en\": \"Generation diversity\", \"zh\": \"生成多样性\"}, \"widget\": \"slider\"}, \"options\": [], \"precision\": 1, \"default_val\": {\"balance\": \"0.8\", \"precise\": \"0.3\", \"creative\": \"1\", \"default_val\": \"1.0\"}}, {\"max\": \"4096\", \"min\": \"1\", \"desc\": {\"en\": \"You can specify the maximum length of the tokens output through this value. Typically, 100 tokens are approximately equal to 150 Chinese characters.\", \"zh\": \"控制模型输出的Tokens 长度上限。通常 100 Tokens 约等于 150 个中文汉字。\"}, \"name\": \"max_tokens\", \"type\": \"int\", \"label\": {\"en\": \"Response max length\", \"zh\": \"最大回复长度\"}, \"style\": {\"label\": {\"en\": \"Input and output settings\", \"zh\": \"输入及输出设置\"}, \"widget\": \"slider\"}, \"options\": [], \"default_val\": {\"default_val\": \"4096\"}}, {\"max\": \"1\", \"min\": \"0\", \"desc\": {\"en\": \"**Top P**:\\\\n\\\\n- An alternative to sampling with temperature, where only tokens within the top p probability mass are considered. For example, 0.1 means only the top 10% probability mass tokens are considered.\\\\n- We recommend altering this or temperature, but not both.\", \"zh\": \"- **Top p 为累计概率**: 模型在生成输出时会从概率最高的词汇开始选择，直到这些词汇的总概率累积达到Top p 值。这样可以限制模型只选择这些高概率的词汇，从而控制输出内容的多样性。建议不要与“生成随机性”同时调整。\"}, \"name\": \"top_p\", \"type\": \"float\", \"label\": {\"en\": \"Top P\", \"zh\": \"Top P\"}, \"style\": {\"label\": {\"en\": \"Generation diversity\", \"zh\": \"生成多样性\"}, \"widget\": \"slider\"}, \"options\": [], \"precision\": 2, \"default_val\": {\"default_val\": \"0.95\"}}]}',1754027126932,1754027126932,NULL),(3,'DeepSeek','deepseek-chat','llm','{\"id\": 2004, \"meta\": {\"name\": \"deepseek-chat\", \"status\": 0, \"protocol\": \"deepseek\", \"capability\": {\"json_mode\": false, \"reasoning\": false, \"max_tokens\": 128000, \"input_modal\": [\"text\"], \"input_tokens\": 128000, \"output_modal\": [\"text\"], \"function_call\": false, \"output_tokens\": 16384, \"prefix_caching\": false, \"prefill_response\": false}, \"conn_config\": {\"stop\": [], \"model\": \"deepseek-chat\", \"top_k\": 0, \"top_p\": 1, \"custom\": {}, \"api_key\": \"REPLACE_ME_MODEL_API_KEY\", \"timeout\": \"10s\", \"base_url\": \"https://api.deepseek.com\", \"deepseek\": {\"response_format_type\": \"text\"}, \"max_tokens\": 4096, \"temperature\": 0.7, \"presence_penalty\": 0, \"frequency_penalty\": 0}}, \"name\": \"deepseek-chat\", \"icon_uri\": \"default_icon/deepseek_v2.png\", \"icon_url\": \"\", \"description\": {\"en\": \"deepseek model description\", \"zh\": \"deepseek 模型简介\"}, \"default_parameters\": [{\"max\": \"1\", \"min\": \"0\", \"desc\": {\"en\": \"**Temperature**:\\\\n\\\\n- When you increase this value, the model outputs more diverse and innovative content; when you decrease it, the model outputs less diverse content that strictly follows the given instructions.\\\\n- It is recommended not to adjust this value with \\\\\\\"Top p\\\\\\\" at the same time.\", \"zh\": \"- **temperature**: 调高温度会使得模型的输出更多样性和创新性，反之，降低温度会使输出内容更加遵循指令要求但减少多样性。建议不要与“Top p”同时调整。\"}, \"name\": \"temperature\", 