 2, \"default_val\": {\"default_val\": \"0.7\"}}, {\"max\": \"\", \"min\": \"\", \"desc\": {\"en\": \"**Response Format**:\\\\n\\\\n- **JSON**: Uses JSON format for replies\", \"zh\": \"- **JSON**: 将引导模型使用JSON格式输出\"}, \"name\": \"response_format\", \"type\": \"int\", \"label\": {\"en\": \"Response format\", \"zh\": \"输出格式\"}, \"style\": {\"label\": {\"en\": \"Input and output settings\", \"zh\": \"输入及输出设置\"}, \"widget\": \"radio_buttons\"}, \"options\": [{\"label\": \"Text\", \"value\": \"0\"}, {\"label\": \"JSON\", \"value\": \"1\"}], \"default_val\": {\"default_val\": \"0\"}}]',1,1,0,1754027126932,1754027126932,NULL),(65547,20,'qwen3-plus-latest','{\"en\":\"通义千问最新的模型moe架构。\",\"zh\":\"通义千问最新的模型moe架构。\"}','[{\"max\": \"1\", \"min\": \"0\", \"desc\": {\"en\": \"**Temperature**:\\n\\n- When you increase this value, the model outputs more diverse and innovative content; when you decrease it, the model outputs less diverse content that strictly follows the given instructions.\\n- It is recommended not to adjust this value with \\\"Top p\\\" at the same time.\", \"zh\": \"- **temperature**: 调高温度会使得模型的输出更多样性和创新性，反之，降低温度会使输出内容更加遵循指令要求但减少多样性。建议不要与\\\"Top p\\\"同时调整。\"}, \"name\": \"temperature\", \"type\": \"float\", \"label\": {\"en\": \"Temperature\", \"zh\": \"生成随机性\"}, \"style\": {\"label\": {\"en\": \"Generation diversity\", \"zh\": \"生成多样性\"}, \"widget\": \"slider\"}, \"precision\": 1, \"default_val\": {\"balance\": \"0.8\", \"precise\": \"0.3\", \"creative\": \"1\", \"default_val\": \"1.0\"}}, {\"max\": \"10000\", \"min\": \"1\", \"desc\": {\"en\": \"You can specify the maximum length of the tokens output through this value. Typically, 100 tokens are approximately equal to 150 Chinese characters.\", \"zh\": \"控制模型输出的Tokens 长度上限。通常 100 Tokens 约等于 150 个中文汉字。\"}, \"name\": \"max_tokens\", \"type\": \"int\", \"label\": {\"en\": \"Response max length\", \"zh\": \"最大回复长度\"}, \"style\": {\"label\": {\"en\": \"Input and output settings\", \"zh\": \"输入及输出设置\"}, \"widget\": \"slider\"}, \"default_val\": {\"default_val\": \"10000\"}}, {\"max\": \"1\", \"min\": \"0\", \"desc\": {\"en\": \"**Top P**:\\n\\n- An alternative to sampling with temperature, where only tokens within the top p probability mass are considered. For example, 0.1 means only the top 10% probability mass tokens are considered.\\n- We recommend altering this or temperature, but not both.\", \"zh\": \"- **Top p 为累计概率**: 模型在生成输出时会从概率最高的词汇开始选择，直到这些词汇的总概率累积达到Top p 值。这样可以限制模型只选择这些高概率的词汇，从而控制输出内容的多样性。建议不要与\\\"生成随机性\\\"同时调整。\"}, \"name\": \"top_p\", \"type\": \"float\", \"label\": {\"en\": \"Top P\", \"zh\": \"Top P\"}, \"style\": {\"label\": {\"en\": \"Generation diversity\", \"zh\": \"生成多样性\"}, \"widget\": \"slider\"}, \"precision\": 2, \"default_val\": {\"default_val\": \"0.95\"}}]',1,1,0,1755153610706,1755404719,NULL),(65548,21,'qwen-flash-2025-07-28','{\"en\":\"qwen model description\",\"zh\":\"通义千问模型\"}','[{\"max\": \"1\", \"min\": \"0\", \"desc\": {\"en\": \"**Temperature**:\\\\n\\\\n- When you increase this value, the model outputs more diverse and innovative content; when you decrease it, the model outputs less diverse content that strictly follows the given instructions.\\\\n- It is recommended not to adjust this value with \\\\\\\"Top p\\\\\\\" at the same time.\", \"zh\": \"- **temperature**: 调高温度会使得模型的输出更多样性和创新性，反之，降低温度会使输出内容更加遵循指令要求但减少多样性。建议不要与“Top p”同时调整。\"}, \"name\": \"temperature\", \"type\": \"float\", \"label\": {\"en\": \"Temperature\", \"zh\": \"生成随机性\"}, \"style\": {\"label\": {\"en\": \"Generation diversity\", \"zh\": \"生成多样性\"}, \"widget\": \"slider\"}, \"precision\": 1, \"default_val\": {\"balance\": \"0.8\", \"precise\": \"0.3\", \"creative\": \"1\", \"default_val\": \"1.0\"}}, {\"max\": \"4096\", \"min\": \"1\", \"desc\": {\"en\": \"You can specify the maximum length of the tokens output through this value. Typically, 100 tokens are approximately equal to 150 Chinese characters.\", \"zh\": \"控制模型输出的Tokens 长度上限。通常 100 Tokens 约等于 150 个中文汉字。\"}, \"name\":